<?php
namespace App\Models;
use App\Domains\Comercial\LiveSales\Enums\EstadoSesionLiveEnum;use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Relations\BelongsTo;use Illuminate\Database\Eloquent\Relations\HasMany;
class SesionLive extends Model { protected $table='sesiones_live'; protected $primaryKey='cod_sesion_live'; protected $fillable=['titulo_ses','fecha_inicio_ses','fecha_fin_ses','estado_ses','resumen_ses','cod_canal_venta','cod_usuario_responsable']; protected $casts=['fecha_inicio_ses'=>'datetime','fecha_fin_ses'=>'datetime','estado_ses'=>EstadoSesionLiveEnum::class]; public function canalVenta():BelongsTo{return $this->belongsTo(CanalVenta::class,'cod_canal_venta','cod_canal_venta');} public function usuarioResponsable():BelongsTo{return $this->belongsTo(User::class,'cod_usuario_responsable','id');} public function productosLive():HasMany{return $this->hasMany(ProductoLive::class,'cod_sesion_live','cod_sesion_live');} public function interaccionesLive():HasMany{return $this->hasMany(InteraccionLive::class,'cod_sesion_live','cod_sesion_live');}}
